<section class="page-heading"><span class="eyebrow">Administration</span><h1>Categories</h1><p>Category names must be unique.</p></section><form method="post" class="form-card inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_category"><div class="field grow"><label for="name">New category name</label><input id="name" name="name" required maxlength="100"></div><button class="button" type="submit">Add category</button></form><div class="table-wrap mt"><table><thead><tr><th>Name</th><th>Slug</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=$c['active']?'Active':'Inactive'?></td><td><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=e($c['id'])?>"><input name="name" value="<?=e($c['name'])?>" required><label><input type="checkbox" name="active" value="1" <?=$c['active']?'checked':''?>> Active</label><button class="button button-small">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div>
